<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from 'vue';
import type { EntityVersion, Utterance, VoiceProfile } from '../../api/bindings';
import { claimPlayback } from '../../composables/playback';
import VoiceSelector from './VoiceSelector.vue';
const props=defineProps<{lines:Utterance[];characters:EntityVersion[];voices:VoiceProfile[];audioUrls?:Record<string,string>;busy?:boolean;editOnly?:boolean;textOnly?:boolean}>();
const emit=defineEmits<{change:[Utterance[]];generate:[string]}>();
const speakerChoices=computed(()=>{const map=new Map<string,EntityVersion>();for(const c of props.characters)if(!map.has(c.id)||map.get(c.id)!.revision<c.revision)map.set(c.id,c);for(const line of props.lines){const pinned=props.characters.find(c=>c.id===line.speaker_id&&c.revision===line.speaker_revision);if(pinned)map.set(pinned.id+':'+pinned.revision,pinned)}return [...new Map([...map.values()].filter(c=>!c.archived).map(c=>[c.id+':'+c.revision,c])).values()]});
const playing=ref('');const playbackError=ref('');let audio:HTMLAudioElement|undefined;
function add(){emit('change',[...props.lines,{id:crypto.randomUUID(),speaker_type:'narrator',text:'',order:props.lines.length}])}
function stop(){audio?.pause();audio=undefined;playing.value=''}
onBeforeUnmount(stop);
async function play(id:string){stop();const url=props.audioUrls?.[id];if(!url)return;const current=new Audio(url);audio=current;current.onended=()=>{if(audio===current)stop()};current.onpause=()=>{if(audio===current)playing.value=''};claimPlayback(current);playbackError.value='';try{await current.play();if(audio===current)playing.value=id}catch{if(audio===current){stop();playbackError.value='音频暂时无法播放，请重试或重新生成。'}}}
function update(i:number,patch:Partial<Utterance>){emit('change',props.lines.map((u,j)=>j===i?{...u,...patch}:u))}
function voice(i:number,value:string){const split=value.lastIndexOf(':');update(i,{voice_profile_id:split<0?undefined:value.slice(0,split),voice_profile_revision:split<0?undefined:Number(value.slice(split+1))})}
function speaker(i:number,value:string){const e=speakerChoices.value.find(c=>c.id+':'+c.revision===value);update(i,{speaker_type:e?'character':'narrator',speaker_id:e?.id,speaker_revision:e?.revision})}
function move(i:number){if(i===0)return;const next=[...props.lines];[next[i-1],next[i]]=[next[i]!,next[i-1]!];emit('change',next.map((u,j)=>({...u,order:j})))}
</script>
<template><section class="dialogue-panel"><h3>{{textOnly?"台词":"台词与音色"}}</h3><p v-if="playbackError" role="alert">{{playbackError}}</p><div v-for="(line,i) in lines" :key="line.id" class="dialogue-row"><select aria-label="说话者" :value="line.speaker_id?line.speaker_id+':'+line.speaker_revision:''" @change="speaker(i,($event.target as HTMLSelectElement).value)"><option value="">旁白</option><option v-for="c in speakerChoices" :key="c.id+':'+c.revision" :value="c.id+':'+c.revision">{{c.name}} · {{c.id.slice(-6)}} · v{{c.revision}}</option></select><textarea aria-label="台词文本" :value="line.text" @input="update(i,{text:($event.target as HTMLTextAreaElement).value})" /><VoiceSelector v-if="!textOnly" :voices="voices" :inherit="line.speaker_type==='character'" :model-value="line.voice_profile_id?line.voice_profile_id+':'+line.voice_profile_revision:''" @update:model-value="voice(i,$event)" /><span v-if="!textOnly">{{line.voice_profile_id?'本句覆盖':line.speaker_type==='character'?'继承人物音色':'旁白需选择音色'}}</span><label v-if="!textOnly">句后停顿（毫秒）<input type="number" min="0" max="10000" step="100" :value="line.pause_after_ms||0" @input="update(i,{pause_after_ms:Number(($event.target as HTMLInputElement).value)})" /></label><button v-if="!editOnly" type="button" :disabled="busy||!line.text.trim()" @click="emit('generate',line.id)">生成配音</button><button v-if="!editOnly" type="button" :disabled="!audioUrls?.[line.id]" @click="playing===line.id?stop():play(line.id)">{{playing===line.id?'停止':'试听'}}</button><button type="button" :disabled="i===0" @click="move(i)">上移</button><button type="button" @click="emit('change',lines.filter(u=>u.id!==line.id).map((u,j)=>({...u,order:j})))">删除台词</button></div><button type="button" @click="add">＋ 添加台词</button></section></template>
